,playBackgroundMusic:function(){if(ig.ua.mobile){ig.game.jukebox.player.resume();}
else{ig.music.play();ig.music.volume=1;}
}
,stopBackgroundMusic:function(){if(ig.ua.mobile){ig.game.jukebox.player.pause();}
else{ig.music.pause();ig.music.volume=0;}
}
,fpsMultiplierFunction:function(){if(!this.fpsTimer){this.fpsTimer=new ig.Timer(1);}
if(this.fpsTimer&&this.fpsTimer.delta()<0){if(this.fpsCounter!=null){this.fpsCounter++;}
else{this.fpsCounter=0;}
}
else{ig.game.fps=this.fpsCounter;this.fpsCounter=0;this.fpsTimer.set(1);}
}
,endGame:function(){console.log('Endgame');if(ig.ua.mobile){if(_SETTINGS['Ad']['Mobile']['End']['Enabled'])MobileAdInGameEnd.Initialize();}
}
